import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse, AxiosError, InternalAxiosRequestConfig } from 'axios';
import { useAuthStore } from '../stores/authStore';
import { RefreshTokenResponse } from '../types/auth';

// API Configuration
const API_BASE_URL = 'https://your-api-domain.com/api'; // Replace with your API URL

// Create axios instance
const api: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Refresh token promise to handle concurrency
let refreshTokenPromise: Promise<string> | null = null;

// Function to refresh token
const refreshToken = async (): Promise<string> => {
  const { refreshToken, setTokens, logout } = useAuthStore.getState();
  
  if (!refreshToken) {
    throw new Error('No refresh token available');
  }

  try {
    const response = await axios.post<RefreshTokenResponse>(
      `${API_BASE_URL}/auth/refresh`,
      { refreshToken },
      {
        headers: {
          'Content-Type': 'application/json',
        },
      }
    );

    const { accessToken, refreshToken: newRefreshToken } = response.data;
    
    // Update tokens in store
    setTokens({
      accessToken,
      refreshToken: newRefreshToken || refreshToken, // Use new refresh token if provided
    });

    return accessToken;
  } catch (error) {
    // If refresh fails, logout user
    logout();
    throw error;
  }
};

// Request interceptor
api.interceptors.request.use(
  async (config: InternalAxiosRequestConfig) => {
    const { accessToken, isTokenExpired } = useAuthStore.getState();
    
    // Skip token logic for public endpoints
    const isPublicEndpoint = config.url?.includes('/auth/login') || 
                           config.url?.includes('/auth/register') ||
                           config.url?.includes('/public');
    
    if (isPublicEndpoint) {
      return config;
    }

    // Check if token is expired
    if (accessToken && isTokenExpired()) {
      // If there's already a refresh in progress, wait for it
      if (refreshTokenPromise) {
        try {
          const newToken = await refreshTokenPromise;
          config.headers = config.headers || {};
          config.headers.Authorization = `Bearer ${newToken}`;
          return config;
        } catch (error) {
          // Refresh failed, continue without token (will be handled by response interceptor)
          return config;
        }
      }

      // Start new refresh
      refreshTokenPromise = refreshToken();
      try {
        const newToken = await refreshTokenPromise;
        config.headers = config.headers || {};
        config.headers.Authorization = `Bearer ${newToken}`;
        refreshTokenPromise = null;
        return config;
      } catch (error) {
        refreshTokenPromise = null;
        return config;
      }
    }

    // Add token to request if available
    if (accessToken) {
      config.headers = config.headers || {};
      config.headers.Authorization = `Bearer ${accessToken}`;
    }

    return config;
  },
  (error: AxiosError) => {
    return Promise.reject(error);
  }
);

// Response interceptor
api.interceptors.response.use(
  (response: AxiosResponse) => {
    return response;
  },
  async (error: AxiosError) => {
    const originalRequest = error.config as AxiosRequestConfig & { _retry?: boolean };
    
    // Handle 401 errors (unauthorized)
    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;
      
      const { refreshToken: currentRefreshToken, logout } = useAuthStore.getState();
      
      // If no refresh token, logout
      if (!currentRefreshToken) {
        logout();
        return Promise.reject(error);
      }

      // Try to refresh token
      if (refreshTokenPromise) {
        try {
          await refreshTokenPromise;
          // Retry the original request
          return api(originalRequest);
        } catch (refreshError) {
          logout();
          return Promise.reject(refreshError);
        }
      } else {
        try {
          refreshTokenPromise = refreshToken();
          await refreshTokenPromise;
          refreshTokenPromise = null;
          // Retry the original request
          return api(originalRequest);
        } catch (refreshError) {
          refreshTokenPromise = null;
          logout();
          return Promise.reject(refreshError);
        }
      }
    }

    return Promise.reject(error);
  }
);

// API methods
export const authAPI = {
  login: async (email: string, password: string) => {
    const response = await api.post('/auth/login', { email, password });
    return response.data;
  },

  register: async (email: string, password: string, name: string) => {
    const response = await api.post('/auth/register', { email, password, name });
    return response.data;
  },

  logout: async () => {
    const response = await api.post('/auth/logout');
    return response.data;
  },

  refreshToken: async (refreshToken: string) => {
    const response = await api.post('/auth/refresh', { refreshToken });
    return response.data;
  },
};

// Generic API methods for protected endpoints
export const protectedAPI = {
  get: async <T>(url: string, config?: AxiosRequestConfig): Promise<T> => {
    const response = await api.get<T>(url, config);
    return response.data;
  },

  post: async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
    const response = await api.post<T>(url, data, config);
    return response.data;
  },

  put: async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
    const response = await api.put<T>(url, data, config);
    return response.data;
  },

  delete: async <T>(url: string, config?: AxiosRequestConfig): Promise<T> => {
    const response = await api.delete<T>(url, config);
    return response.data;
  },

  patch: async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> => {
    const response = await api.patch<T>(url, data, config);
    return response.data;
  },
};

export default api; 